// Claude's review tests for A34 in the panel: hints in the code editor and the Run button.
// agy: do not edit this file.
import { expect, test } from '@playwright/test';
import { emptyState, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

const codeMock: Mock = {
  id: 'c', name: 'User by id', enabled: true, method: 'POST', urlPattern: '/api/users/:id', source: 'manual', createdAt: 0,
  reply: 'code', code: 'return { id: params.id, got: body };',
  response: { status: 201, headers: { 'content-type': 'application/json' }, body: '', bodyEncoding: 'text', delayMs: 0 },
};

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function openEditor() {
  const p: Project = { id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default', scenarios: [{ id: 'default', name: 'Default', mocks: [codeMock] }] };
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  await panel.getByTestId('tab-mocks').click();
  await panel.getByTestId('mock-row').filter({ hasText: 'User by id' }).click();
  await expect(panel.getByTestId('code-view')).toBeVisible();
  return { page, panel };
}

test('typing req. and params. in the code shows the hints', async () => {
  const { page, panel } = await openEditor();
  try {
    const editor = panel.getByTestId('code-view').locator('.cm-content');
    await editor.click();
    await panel.keyboard.press('Control+End');
    await panel.keyboard.press('Enter');
    await panel.keyboard.type('req.');
    const tip = panel.locator('.cm-tooltip-autocomplete');
    await expect(tip).toBeVisible();
    await expect(tip).toContainText('params');
    await expect(tip).toContainText('callCount');
    await panel.keyboard.press('Escape');
    await panel.keyboard.press('Enter');
    await panel.keyboard.type('params.');
    await expect(panel.locator('.cm-tooltip-autocomplete')).toContainText('id');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Run tries the code as typed, before Save, and shows the answer or the error', async () => {
  const { page, panel } = await openEditor();
  try {
    await expect(panel.getByTestId('code-try-url')).toHaveValue(`${fixture.origin}/api/users/1`);
    await panel.getByTestId('code-try-url').fill(`${fixture.origin}/api/users/42`);
    await panel.getByTestId('code-try-body').fill('{"name":"Cy"}');
    await panel.getByTestId('code-run').click();
    const out = panel.getByTestId('code-run-out');
    await expect(out).toContainText('201');
    await expect(out).toContainText('"id":"42"');
    await expect(out).toContainText('"name":"Cy"');

    // A path alone is read against the page's origin, so :id still fills in (found in A36).
    await panel.getByTestId('code-try-url').fill('/api/users/7');
    await panel.getByTestId('code-run').click();
    await expect(out).toContainText('"id":"7"');

    // Change the code without saving: Run uses the new text.
    const editor = panel.getByTestId('code-view').locator('.cm-content');
    await editor.click();
    await panel.keyboard.press('Control+A');
    await panel.keyboard.type("throw new Error('out of tea')");
    await panel.getByTestId('code-run').click();
    await expect(panel.getByTestId('code-run-error')).toContainText('out of tea');
    // Nothing was saved.
    expect((await readState()).projects[0]!.scenarios[0]!.mocks[0]!.code).toBe(codeMock.code);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the body box shows only for methods with a body', async () => {
  const { page, panel } = await openEditor();
  try {
    await expect(panel.getByTestId('code-try-body')).toBeVisible();
    await panel.getByTestId('field-method').selectOption('GET');
    await expect(panel.getByTestId('code-try-body')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});
